sql.where:
t_chat_topic_category.is_delete = 0

        and t_chat_topic_category.id = #{id}


        and t_chat_topic_category.parent_id = #{parentId}


        and t_chat_topic_category.name = #{name}


        and t_chat_topic_category.description = #{description}


        and t_chat_topic_category.to_do = #{toDo}


        and t_chat_topic_category.important = #{important}


        and t_chat_topic_category.sort_order = #{sortOrder}


        and t_chat_topic_category.is_leaf = #{isLeaf}


        and t_chat_topic_category.status = #{status}


        and t_chat_topic_category.created_at = #{createdAt}


        and t_chat_topic_category.updated_at = #{updatedAt}

mapper.select:
WITH RECURSIVE tree AS (
    SELECT , 0 AS level
    FROM t_chat_topic_category
    WHERE parent_id = #{id}
    UNION ALL
    SELECT , tree.level + 1 AS level
    FROM t_chat_topic_category t
             JOIN tree ON t.parent_id = tree.id
)
SELECT * FROM tree WHERE level <= #{level};
